const UsesRelPreconnect = require('../../audits/uses-rel-preconnect.js');
const assert = require('assert');
const networkRecordsToDevtoolsLog = require('../network-records-to-devtools-log.js');

const mainResource = {
  url: 'https://ericbidelman.com',
  parsedURL: {
    securityOrigin: 'https://ericbidelman.com',
  },
  endTime: 1,
};

async function testPreconnectAudit() {
  const networkRecords = [
    mainResource,
    {
      url: 'https://www.google-analytics.com',
      initiator: {},
      timing: {
        dnsStart: -1,
        dnsEnd: -1,
        connectEnd: -1,
        connectStart: -1,
        receiveHeadersEnd: 3,
      },
    },
    {
      url: 'https://fonts.gstatic.com',
      initiator: {},
      timing: {
        dnsStart: -1,
        dnsEnd: -1,
        connectEnd: -1,
        connectStart: -1,
        receiveHeadersEnd: 3,
      },
    },
  ];

  const artifacts = {
    devtoolsLogs: {[UsesRelPreconnect.DEFAULT_PASS]: networkRecordsToDevtoolsLog(networkRecords)},
    URL: {finalUrl: mainResource.url},
  };

  const context = {settings: {}, computedCache: new Map()};
  const {score, rawValue, details} = await UsesRelPreconnect.audit(artifacts, context);
  assert.equal(score, 1);
  assert.equal(rawValue, 0);
  assert.equal(details.items.length, 0);
}

testPreconnectAudit().then(() => console.log('Test passed')).catch(err => console.error('Test failed', err));
